526	/// RFC 6962-bis recursive inclusion recomputation: the combination order is
527	/// derived from the subtree sizes, and the path is consumed in its given
528	/// leaf-to-root order. A missing sibling or an unconsumed leftover hash is an
529	/// error, so an over- or under-long path never verifies. Arithmetic stays in
530	/// u64 so sizes above `usize::MAX` cannot truncate on a 32-bit platform; the
531	/// recursion depth is bounded by the hashes actually present in the path.
532	fn include_record(
533	    leaf: [u8; 32],
534	    m: u64,
535	    n: u64,
536	    path: &[[u8; 32]],
537	) -> Result<[u8; 32], String> {
538	    fn sub(
539	        leaf: [u8; 32],
540	        m: u64,
541	        n: u64,
542	        path: &[[u8; 32]],
543	        pos: &mut usize,
544	    ) -> Result<[u8; 32], String> {
545	        if n == 1 {
546	            return Ok(leaf);
547	        }
548	        // Largest power of two strictly smaller than n.
549	        let k = 1u64 << (u64::BITS - 1 - (n - 1).leading_zeros());
550	        if m < k {
551	            let left = sub(leaf, m, k, path, pos)?;
552	            let right = take(path, pos)?;
553	            Ok(node_hash(&left, &right))
554	        } else {
555	            let right = sub(leaf, m - k, n - k, path, pos)?;
556	            let left = take(path, pos)?;
557	            Ok(node_hash(&left, &right))
558	        }
559	    }
560	    fn take(path: &[[u8; 32]], pos: &mut usize) -> Result<[u8; 32], String> {
561	        let h = *path
562	            .get(*pos)
563	            .ok_or_else(|| "audit_path is shorter than the tree requires".to_string())?;
564	        *pos += 1;
565	        Ok(h)
566	    }
567	    let mut pos = 0;
568	    let root = sub(leaf, m, n, path, &mut pos)?;
569	    if pos != path.len() {
570	        return Err("audit_path is longer than the tree requires".to_string());
571	    }
572	    Ok(root)
573	}
