590	/// A fresh leaf hasher primed with the RFC 6962 section 2.1 leaf prefix 0x00.
591	fn new_leaf_hasher() -> Sha256 {
592	    let mut h = Sha256::new();
593	    h.update(&[0x00]);
594	    h
595	}
