616	/// Construct the RFC 6962 Merkle tree over a batch. This is the SINGLE place
617	/// that maintains the tree-construction rules: both `root` (via `mth`) and
618	/// `prove` (via `root_and_path`) build their leaves and subtrees here, so the
619	/// two commands can never disagree on how a batch is shaped or hashed.
620	///
621	/// ```text
622	/// MTH([])      = SHA-256("")
623	/// MTH([d])     = SHA-256(0x00 || d)
624	/// MTH(d0..dn)  = SHA-256(0x01 || MTH(d0..dk) || MTH(dk..dn))
625	/// ```
626	///
627	/// with k the largest power of two strictly smaller than n. Uneven batches
628	/// are handled by the recursion itself: no leaf is duplicated and no empty
629	/// record is appended to round the size up to a power of two.
630	///
631	/// `target` selects the one leaf a membership proof is built for:
632	///
633	/// ```text
634	/// PATH(m, [d0]) = []
635	/// PATH(m, [d0..d(n-1)]) = PATH(m, [d0..d(k-1)]) + MTH([dk..d(n-1)])   if m < k
636	///                       = PATH(m, [dk..d(n-1)]) + MTH([d0..d(k-1)])   if m >= k
637	/// ```
638	///
639	/// When `target` is `Some(m)`, the sibling subtree hashes on the route from
640	/// leaf `m` to the root are appended to `path` in leaf-to-root order
641	/// (RFC 6962 section 2.1.1); the reindexed `Some(m - k)` follows the audited
642	/// leaf into whichever subtree contains it, while the sibling subtree is
643	/// built with `None`. With `None` only the root is built. Every leaf hash and
644	/// every interior hash is computed exactly once in either mode, so producing
645	/// a proof costs the same 2n - 1 SHA-256 invocations as the root alone.
646	fn build_tree(
647	    leaves: &[&[u8]],
648	    target: Option<usize>,
649	    path: &mut Vec<[u8; 32]>,
650	) -> [u8; 32] {
651	    match leaves.len() {
652	        0 => sha256(&[]),
653	        1 => leaf_hash(leaves[0]),
654	        n => {
655	            // Largest power of two strictly smaller than n.
656	            let k = 1usize << (usize::BITS - 1 - (n - 1).leading_zeros());
657	            let (left_leaves, right_leaves) = leaves.split_at(k);
658	            match target {
659	                // The audited leaf is in the left subtree; the right subtree
660	                // hash is this level's sibling on the leaf-to-root path.
661	                Some(m) if m < k => {
662	                    let left = build_tree(left_leaves, Some(m), path);
663	                    let right = build_tree(right_leaves, None, path);
664	                    path.push(right);
665	                    node_hash(&left, &right)
666	                }
667	                // The audited leaf is in the right subtree; reindex it
668	                // relative to that subtree and take the left subtree as the
669	                // sibling.
670	                Some(m) => {
671	                    let left = build_tree(left_leaves, None, path);
672	                    let right = build_tree(right_leaves, Some(m - k), path);
673	                    path.push(left);
674	                    node_hash(&left, &right)
675	                }
676	                // No audited leaf: both subtrees are plain root constructions.
677	                None => {
678	                    let left = build_tree(left_leaves, None, path);
679	                    let right = build_tree(right_leaves, None, path);
680	                    node_hash(&left, &right)
681	                }
682	            }
683	        }
684	    }
685	}
