695	/// RFC 6962 section 2.1.1: the Merkle Tree Hash of the whole batch together
696	/// with the Merkle Audit Path for the record at `m`, both produced by the
697	/// shared `build_tree` constructor. The returned path is ordered from the
698	/// leaf level up to the root and is empty for a batch of exactly one record.
699	#[doc(hidden)]
700	pub fn root_and_path(leaves: &[&[u8]], m: usize) -> ([u8; 32], Vec<[u8; 32]>) {
701	    let n = leaves.len();
702	    assert!(m < n, "leaf index {m} out of range for {n} record(s)");
703	    let mut path = Vec::new();
704	    let root = build_tree(leaves, Some(m), &mut path);
705	    (root, path)
706	}
