708	// --- Streaming root computation ---------------------------------------------
709	//
710	// `roottrace root` must not hold the batch in memory: the file is read through
711	// a fixed-size buffer, every record is hashed as it streams past (a record is
712	// never stored, however long it is), and the only per-record state kept is
713	// the stack of completed subtree hashes below — at most one entry per bit of
714	// the record count, so O(log n) hashes independent of the file's byte length
715	// and of the longest record.
716	
717	/// Incremental RFC 6962 Merkle Tree Hash over an LF-separated byte stream.
718	///
719	/// Bytes are fed through [`RootStream::feed`] in chunks of any size; how many
720	/// bytes one read returns is meaningless to the result, and a record that
721	/// spans any number of chunks is hashed in full. Records are delimited by LF
722	/// exactly as [`split_records`] defines (the separator is not content, a
723	/// trailing LF only terminates the last record, an empty input is zero
724	/// records), and the tree is folded with the same largest-power-of-two split
725	/// as `build_tree`, so [`RootStream::finish`] returns exactly
726	/// `mth(&split_records(whole))` for the concatenation `whole` of everything
727	/// fed.
728	///
729	/// Memory use is a small fixed amount plus at most 64 subtree hashes (one per
730	/// bit of the record count): nothing grows with the number of bytes fed or
731	/// with the length of any single record.
732	#[doc(hidden)]
733	pub struct RootStream {
734	    /// Hasher for the record currently being accumulated, primed with 0x00.
735	    leaf: Sha256,
736	    /// Whether any content byte of the current record has been seen. A record
737	    /// only exists once it has content or is terminated by an LF, so an empty
738	    /// input is zero records and a trailing LF adds none.
739	    record_has_bytes: bool,
740	    /// Completed subtree hashes, bottom to top in strictly decreasing height;
741	    /// entry i covers 2^height consecutive leaves. Together the entries are
742	    /// the binary decomposition of the record count so far, which is exactly
743	    /// the shape the recursive largest-power-of-two split produces.
744	    subtrees: Vec<([u8; 32], u32)>,
745	}
746	
747	impl RootStream {
748	    #[doc(hidden)]
749	    pub fn new() -> Self {
750	        RootStream {
751	            leaf: new_leaf_hasher(),
752	            record_has_bytes: false,
753	            subtrees: Vec::new(),
754	        }
755	    }
756	
757	    /// Feed the next chunk of input. LF bytes split records and are not
758	    /// content; every other byte — space, tab, CR, NUL, non-UTF-8 — is hashed
759	    /// into the current record as-is.
760	    #[doc(hidden)]
761	    pub fn feed(&mut self, mut chunk: &[u8]) {
762	        while let Some(pos) = chunk.iter().position(|&b| b == b'\n') {
763	            self.leaf.update(&chunk[..pos]);
764	            self.record_has_bytes |= pos > 0;
765	            self.finish_record();
766	            chunk = &chunk[pos + 1..];
767	        }
768	        self.leaf.update(chunk);
769	        self.record_has_bytes |= !chunk.is_empty();
770	    }
771	
772	    /// Close the current record: finalize its leaf hash and fold it into the
773	    /// subtree stack, merging completed subtrees of equal height so the stack
774	    /// always holds the largest complete subtrees on the left.
775	    fn finish_record(&mut self) {
776	        let leaf = std::mem::replace(&mut self.leaf, new_leaf_hasher()).finalize();
777	        self.record_has_bytes = false;
778	        let mut acc = leaf;
779	        let mut height = 0u32;
780	        while self.subtrees.last().is_some_and(|&(_, h)| h == height) {
781	            let (left, _) = self.subtrees.pop().unwrap();
782	            acc = node_hash(&left, &acc);
783	            height += 1;
784	        }
785	        self.subtrees.push((acc, height));
786	    }
787	
788	    /// Produce the batch root. A final record without a terminating LF counts
789	    /// in full; a trailing LF adds no record; no input at all is the RFC 6962
790	    /// empty-tree hash SHA-256("").
791	    #[doc(hidden)]
792	    pub fn finish(mut self) -> [u8; 32] {
793	        if self.record_has_bytes {
794	            self.finish_record();
795	        }
796	        match self.subtrees.pop() {
797	            None => sha256(&[]),
798	            Some((mut acc, _)) => {
799	                // Fold the remaining complete subtrees right to left: reading
800	                // the binary decomposition of the record count this way is
801	                // the recursive k-split of build_tree.
802	                while let Some((left, _)) = self.subtrees.pop() {
803	                    acc = node_hash(&left, &acc);
804	                }
805	                acc
806	            }
807	        }
808	    }
809	}
