818	pub fn hex(digest: &[u8; 32]) -> String {
819	    let mut s = String::with_capacity(64);
820	    for b in digest {
821	        s.push(char::from_digit((b >> 4) as u32, 16).unwrap());
822	        s.push(char::from_digit((b & 0x0f) as u32, 16).unwrap());
823	    }
824	    s
825	}
