827	/// Build the one-line JSON object printed by `prove`: integer tree_size and
828	/// leaf_index, the lowercase-hex root, and the audit path as a JSON array of
829	/// lowercase-hex hashes ordered leaf to root.
830	#[doc(hidden)]
831	pub fn proof_json(tree_size: u64, leaf_index: u64, root: &[u8; 32], audit_path: &[[u8; 32]]) -> String {
832	    let mut out = String::new();
