874	/// One-shot SHA-256 over a byte slice, kept for the empty-tree root and for
875	/// callers that already hold the whole input. Streams through `Sha256`, so it
876	/// performs no copy of `data` itself.
877	fn sha256(data: &[u8]) -> [u8; 32] {
878	    let mut h = Sha256::new();
879	    h.update(data);
880	    h.finalize()
881	}
