1013	    /// Verify an RFC 6962 inclusion proof with the RFC's recursive verifier:
1014	    /// it re-derives the combination order from the tree geometry (k =
1015	    /// largest power of two below the current subtree size) while consuming
1016	    /// exactly the supplied sibling hashes. A wrong length, order or hash
1017	    /// fails; the root computed here must equal the tree root.
1018	    fn rfc_recompute_root(leaf: &[u8], m: usize, n: usize, path: &[[u8; 32]]) -> [u8; 32] {
1019	        assert!(m < n);
1020	        fn sub(leaf: &[u8], m: usize, n: usize, path: &[[u8; 32]], pos: &mut usize) -> [u8; 32] {
1021	            if n == 1 {
1022	                return leaf_hash(leaf);
1023	            }
1024	            let k = 1usize << (usize::BITS - 1 - (n - 1).leading_zeros());
1025	            if m < k {
1026	                let left = sub(leaf, m, k, path, pos);
1027	                assert!(*pos < path.len(), "proof too short");
1028	                let right = path[*pos];
1029	                *pos += 1;
1030	                node_hash(&left, &right)
1031	            } else {
1032	                let right = sub(leaf, m - k, n - k, path, pos);
1033	                assert!(*pos < path.len(), "proof too short");
1034	                let left = path[*pos];
1035	                *pos += 1;
1036	                node_hash(&left, &right)
1037	            }
1038	        }
1039	        let mut pos = 0;
1040	        let root = sub(leaf, m, n, path, &mut pos);
1041	        assert_eq!(pos, path.len(), "proof too long: {pos} consumed of {}", path.len());
1042	        root
1043	    }
