1406	    fn parse_proof_rejects_missing_fields_and_empty_or_wrong_container() {
1407	        let refs: Vec<&[u8]> = vec![b"a", b"b"];
1408	        let (root, path) = root_and_path(&refs, 0);
1409	        let full = valid_proof_bytes(2, 0, &root, &path);
1410	        assert!(parse_proof(&full).is_ok());
1411	
1412	        let drop_field = |bytes: &[u8], needle: &str| -> Vec<u8> {
1413	            let text = String::from_utf8(bytes.to_vec()).unwrap();
1414	            // Rebuild without the named member by string surgery on the
1415	            // canonical compact form emitted by proof_json.
1416	            let idx = text.find(needle).unwrap();
1417	            let mut end = idx + needle.len();
1418	            // Consume through the member's value terminator.
1419	            match needle {
1420	                "\"tree_size\":" | "\"leaf_index\":" => {
1421	                    while end < text.len()
1422	                        && text.as_bytes()[end] != b','
1423	                        && text.as_bytes()[end] != b'}'
1424	                    {
1425	                        end += 1;
1426	                    }
1427	                }
1428	                "\"root\":" => {
1429	                    while end < text.len() && text.as_bytes()[end] != b'"' {
1430	                        end += 1;
1431	                    }
1432	                    end += 1;
1433	                }
1434	                _ => {
1435	                    end = text.rfind(']').unwrap() + 1;
1436	                }
1437	            }
1438	            let mut s = String::new();
1439	            s.push_str(&text[..idx]);
1440	            let rest = &text[end..];
1441	            // Tidy the separator left by the removed member.
1442	            if rest.starts_with(',') {
1443	                s.push_str(&rest[1..]);
1444	            } else if text[..idx].ends_with(',') {
1445	                s.pop();
1446	                s.push_str(rest);
1447	            } else {
1448	                s.push_str(rest);
1449	            }
1450	            s.into_bytes()
1451	        };
1452	
1453	        for key in ["\"tree_size\":", "\"leaf_index\":", "\"root\":", "\"audit_path\":"] {
1454	            let cut = drop_field(&full, key);
1455	            assert!(parse_proof(&cut).is_err(), "proof missing {key} must be invalid: {cut:?}");
1456	        }
1457	
1458	        for bad in [
1459	            b"".as_slice(),
1460	            b"   ",
1461	            b"null",
1462	            b"[]",
1463	            b"\"x\"",
1464	            b"123",
1465	            b"{}",
1466	            b"[{\"tree_size\":1}]",
1467	        ] {
1468	            assert!(parse_proof(bad).is_err(), "{bad:?} must not parse as a proof");
1469	        }
1470	    }
