1574	    /// Build a real proof object (as produced by `prove`) for one record of a
1575	    /// batch, then verify it exactly the way the command does.
1576	    fn verify_record(records: &[&[u8]], m: usize, record: &[u8], trusted_size: u64) -> Result<(), String> {
1577	        let (root, path) = root_and_path(records, m);
1578	        let size = records.len() as u64;
1579	        let bytes = proof_json(size, m as u64, &root, &path).into_bytes();
1580	        let proof = parse_proof(&bytes).unwrap();
1581	        verify_proof(&proof, record, trusted_size, &root)
1582	    }
