1	//! End-to-end regression tests for `roottrace root`, focused on the power-of
2	//! two boundary in the RFC 6962 SHA-256 Merkle Tree Hash (7, 8 and 9
3	//! records).
4	//!
5	//! Expected roots are FIXED constants produced independently of roottrace by
6	//! `tests/reference/rfc6962_vectors.py`, which computes them with Python's
7	//! `hashlib.sha256` in two structurally different ways (the RFC's recursive
8	//! definition and an order-sensitive stack fold); the two implementations
9	//! agree for every vector, and the one-leaf/empty cases were additionally
10	//! cross-checked against the system `sha256sum`. The constants below are
11	//! copied from that generator and never derived from roottrace output.
12	//!
13	//! Each batch is spelled out as its exact record sequence so an expected root
14	//! can be traced back to the records it belongs to. Failures distinguish a
15	//! command execution failure from a root mismatch and report both the record
16	//! sequence and the expected root.
17	
18	mod common;
19	
20	use std::process::Command;
21	
22	use common::{assert_root, join_lf, TempDir, TempFile};
23	
24	// ---------------------------------------------------------------------------
25	// Fixed record sequences.
26	//
27	// The 7/8/9 batches share their first seven records. Those seven include:
28	//   * duplicated content at two different positions (r0 == r4 == b"alpha")
29	//   * an empty record (r2)
30	//   * a trailing CR kept as content (r5)
31	//   * non-UTF-8 / NUL bytes (r6)
32	// The eighth and ninth records are explicitly defined and distinct.
33	// ---------------------------------------------------------------------------
34	
35	const B7: &[&[u8]] = &[
36	    b"alpha",
37	    b"beta",
38	    b"",
39	    b"gamma",
40	    b"alpha",
41	    b"delta\r",
42	    b"\xff\xfe\x00binary",
43	];
44	
45	const B8: &[&[u8]] = &[
46	    b"alpha",
47	    b"beta",
48	    b"",
49	    b"gamma",
50	    b"alpha",
51	    b"delta\r",
52	    b"\xff\xfe\x00binary",
53	    b"epsilon",
54	];
55	
56	const B9: &[&[u8]] = &[
57	    b"alpha",
58	    b"beta",
59	    b"",
60	    b"gamma",
61	    b"alpha",
62	    b"delta\r",
63	    b"\xff\xfe\x00binary",
64	    b"epsilon",
65	    b"zeta\x01tail",
66	];
67	
68	// Independently fixed RFC 6962 roots (tests/reference/rfc6962_vectors.py).
69	const ROOT_B7: &str = "90caa8bddc2a50cf863a969533ad1700a80aeed313dcd1c7a4b46b0c93991b6e";
70	const ROOT_B8: &str = "80f3f98ae8d7d9d1d2139a6a2dc94628e02fba22e125f922ea8a4c10799cb912";
71	const ROOT_B9: &str = "a8a3e76ecf28b850e84cb5465729921212ffd07de3c0e6e170cd233bf723adc3";
72	
73	// B9 with the duplicate-content position r4 changed to other bytes.
74	const V_DUP: &[&[u8]] = &[
75	    b"alpha",
76	    b"beta",
77	    b"",
78	    b"gamma",
79	    b"alpha-changed",
80	    b"delta\r",
81	    b"\xff\xfe\x00binary",
82	    b"epsilon",
83	    b"zeta\x01tail",
84	];
85	const ROOT_V_DUP: &str = "015cce68e9e800f3ff480da17c8f43f30eed95e0705b5500043c3bf74662dde0";
86	
87	// B9 with two records of different content (r1 and r5) swapped. The byte
88	// multiset of records is unchanged, only their positions differ.
89	const V_SWAP: &[&[u8]] = &[
90	    b"alpha",
91	    b"delta\r",
92	    b"",
93	    b"gamma",
94	    b"alpha",
95	    b"beta",
96	    b"\xff\xfe\x00binary",
97	    b"epsilon",
98	    b"zeta\x01tail",
99	];
100	const ROOT_V_SWAP: &str = "3a6482dbcf43884e11018c885ff68e63717a13154217c591c8a01f6dafdb9dd9";
101	
102	// B9 with the empty record r2 omitted: 8 records, but a DIFFERENT sequence
103	// from B8. Dropping an empty record must not be silently ignored.
104	const V_DROP_EMPTY: &[&[u8]] = &[
105	    b"alpha",
106	    b"beta",
107	    b"gamma",
108	    b"alpha",
109	    b"delta\r",
110	    b"\xff\xfe\x00binary",
111	    b"epsilon",
112	    b"zeta\x01tail",
113	];
114	const ROOT_V_DROP_EMPTY: &str = "918ae84b0d065be5148d048875c9f8cafb5e0ee14417cefbbbb4575631a5257a";
115	
116	// B9 with one extra duplicate of r0 appended: the same record content
117	// included twice occupies two positions (10 records total).
118	const V_DUP_INSERT: &[&[u8]] = &[
119	    b"alpha",
120	    b"beta",
121	    b"",
122	    b"gamma",
123	    b"alpha",
124	    b"delta\r",
125	    b"\xff\xfe\x00binary",
126	    b"epsilon",
127	    b"zeta\x01tail",
128	    b"alpha",
129	];
130	const ROOT_V_DUP_INSERT: &str = "ae0586f6c285c304a53273198d19f5f137d1d9f546e9a74a6fd87547c09bd4e8";
131	
132	// Empty file: zero records -> SHA-256(""). Single LF: one empty record ->
133	// SHA-256(0x00). Independently fixed (and cross-checked with sha256sum).
134	const ROOT_EMPTY_FILE: &str =
135	    "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855";
136	const ROOT_ONE_EMPTY_RECORD: &str =
137	    "6e340b9cffb37a989ca544e6bb780a2c78901d3fb33738768511a30617afa01d";
138	
139	#[test]
140	fn roots_for_7_8_and_9_records_match_fixed_vectors() {
141	    assert_root(
142	        "B7: seven records (largest subtree split k=4, uneven right side)",
143	        B7,
144	        &join_lf(B7, true),
145	        ROOT_B7,
146	    );
147	    assert_root(
148	        "B8: eight records exactly fills a depth-3 tree (power-of-two boundary)",
149	        B8,
150	        &join_lf(B8, true),
151	        ROOT_B8,
152	    );
153	    assert_root(
154	        "B9: nine records crosses the 8-record power-of-two boundary (k=8)",
155	        B9,
156	        &join_lf(B9, true),
157	        ROOT_B9,
158	    );
159	}
160	
161	#[test]
162	fn changing_one_duplicate_position_gives_its_own_fixed_root() {
163	    assert_root(
164	        "V_DUP: r4 (byte-equal to r0) changed, exact new root",
165	        V_DUP,
166	        &join_lf(V_DUP, true),
167	        ROOT_V_DUP,
168	    );
169	    assert_ne!(ROOT_V_DUP, ROOT_B9, "changed record must change the root");
170	}
171	
172	#[test]
173	fn swapping_two_different_records_gives_its_own_fixed_root() {
174	    assert_root(
175	        "V_SWAP: r1 and r5 swapped; same record contents, different positions",
176	        V_SWAP,
177	        &join_lf(V_SWAP, true),
178	        ROOT_V_SWAP,
179	    );
180	    assert_ne!(ROOT_V_SWAP, ROOT_B9, "record order participates in the hash");
181	    // Equal contents at different positions are not interchangeable: while the
182	    // swap moved r1/r5, untouched duplicate positions r0 and r4 still prove
183	    // per-position participation via V_DUP's fixed root above.
184	}
185	
186	#[test]
187	fn omitting_the_empty_record_gives_its_own_fixed_root() {
188	    assert_eq!(V_DROP_EMPTY.len(), 8);
189	    assert_ne!(V_DROP_EMPTY, B8, "8 records here is not the B8 sequence");
190	    assert_root(
191	        "V_DROP_EMPTY: empty r2 removed; empty records occupy a real position",
192	        V_DROP_EMPTY,
193	        &join_lf(V_DROP_EMPTY, true),
194	        ROOT_V_DROP_EMPTY,
195	    );
196	    assert_ne!(ROOT_V_DROP_EMPTY, ROOT_B9);
197	    assert_ne!(ROOT_V_DROP_EMPTY, ROOT_B8, "must not collide with B8's 8-record root");
198	}
199	
200	#[test]
201	fn including_a_duplicate_record_twice_gives_its_own_fixed_root() {
202	    assert_eq!(V_DUP_INSERT.len(), 10);
203	    assert_root(
204	        "V_DUP_INSERT: duplicate of r0 appended; duplicates are not merged",
205	        V_DUP_INSERT,
206	        &join_lf(V_DUP_INSERT, true),
207	        ROOT_V_DUP_INSERT,
208	    );
209	    assert_ne!(ROOT_V_DUP_INSERT, ROOT_B9);
210	}
211	
212	#[test]
213	fn trailing_lf_only_terminates_the_last_record() {
214	    // The same fixed sequence with and without a final LF has the same fixed
215	    // root, on both sides of the power-of-two boundary.
216	    for (desc, records, expected) in [
217	        ("B7 trailing/no-trailing LF", B7, ROOT_B7),
218	        ("B8 trailing/no-trailing LF", B8, ROOT_B8),
219	        ("B9 trailing/no-trailing LF", B9, ROOT_B9),
220	    ] {
221	        assert_root(desc, records, &join_lf(records, true), expected);
222	        assert_root(desc, records, &join_lf(records, false), expected);
223	    }
224	}
225	
226	#[test]
227	fn empty_file_is_zero_records_single_lf_is_one_empty_record() {
228	    assert_root("EMPTY: 0-byte file, zero records", &[], b"", ROOT_EMPTY_FILE);
229	    assert_root(
230	        "ONE_LF: one LF, a single empty record",
231	        &[b""],
232	        b"\n",
233	        ROOT_ONE_EMPTY_RECORD,
